# English content. Each entry mirrors a French page (key "fr" = French slug) for hreflang.
GUIDES_EN = [
dict(fr="cavitation-pompe", slug="pump-cavitation", machine="Pump", domaine="Industrial machinery", niveau="Intermediate",
 h1="Pump making a gravel noise: how to recognise cavitation",
 title="Pump making a gravel noise: cavitation",
 desc="Gravel noise, vibration, falling flow: how to recognise cavitation in a centrifugal pump, what to check and what to do before it breaks.",
 intro="A centrifugal pump that sounds like it is pumping gravel is usually cavitating: suction pressure is too low, small vapour bubbles form and then collapse on the impeller. The impeller wears silently for weeks, then the flow collapses. Borehole pumps, booster sets, process water, washing: every centrifugal pump can be affected.",
 signes=["A crackling noise, like gravel going through the pump.","Increasing, often irregular vibration.","Discharge flow or pressure falling or fluctuating.","The motor runs but the pump “pushes” less than before."],
 causes=[("Blocked suction strainer or filter","Visual inspection, machine stopped and locked out"),("Suction valve partly closed","The valve must be fully open"),("Level too low in the tank or well","Water level, dry-run protection"),("Liquid too hot, suction line too long or too narrow","Liquid temperature, suction line layout"),("Air entering on the suction side","Seals, fittings and gland on the suction side")],
 faire=["Machine stopped and locked out: clean the strainer or filter, open the suction valve fully, tighten or replace the leaking seal.","Throttle flow on the discharge side, never by closing the suction.","Restore a sufficient water level before restarting, or protect the pump against dry running.","If the noise persists, have the pump inspected: the impeller may already be eroded. Ordering the part before failure costs less than downtime.","Record date, noise and pressure to follow the trend."],
 secu="Never work on a running pump: lockout/tagout before opening a strainer or filter.",
 faq=[("Can I control pump flow by closing the suction valve?","No. Closing the suction lowers the inlet pressure and causes cavitation. Flow is throttled on the discharge valve."),("Does cavitation really damage the pump?","Yes. Collapsing bubbles erode the impeller and make the pump vibrate, which also wears the bearings and the mechanical seal.")],
 related=["noisy-bearing","electric-motor-overheating","generator-will-not-start"]),
dict(fr="roulement-qui-siffle-ou-gronde", slug="noisy-bearing", machine="Bearings", domaine="Industrial machinery", niveau="Simple",
 h1="Bearing whistling or rumbling: what to do before it fails",
 title="Noisy bearing: whistling, rumbling, knocking",
 desc="Whistling, rumbling, knocking, heat: what a bearing noise means, how to check it with a stethoscope and when to replace it.",
 intro="Bearings are the wear part of every rotating machine: motors, pumps, fans, conveyors. They almost always warn before failing, through noise and temperature. A whistle is not as serious as a rumble or a knock.",
 signes=["A high-pitched, steady whistle.","A rumbling, rough noise.","Irregular knocking.","A bearing housing hotter than usual or than its neighbour.","Rising vibration on the housing."],
 causes=[("Whistle: lack of grease","Stethoscope before and after greasing"),("Heat right after greasing: too much grease","Quantity injected, purge of old grease"),("Rumble: damaged raceways","Stethoscope, vibration trend"),("Knocking and strong heat: advanced damage, broken cage","Temperature and noise compared with the other bearing"),("Repeated failures: misalignment, unbalance, contamination, poor fitting","Alignment, seals, inspection of the removed bearing")],
 faire=["Whistle: grease with the grease and quantity specified in the manual, then listen again a few minutes later. If the noise returns within days, the bearing is already damaged.","Rumble: order the bearing and replace it at the next planned stop.","Knocking with strong heat: stop quickly, before the shaft and housing are damaged.","After replacement, find out why it failed, or the new bearing will die the same way."],
 secu="Listen with a stethoscope on a fixed part only (bearing cap), never near moving parts.",
 faq=[("Should I add more grease to silence a bearing?","No. Use the right grease and the right quantity. Too much grease makes a bearing run hot. Never mix incompatible greases."),("How can I hear a single bearing?","With a mechanical stethoscope placed on the bearing cap, comparing with the other bearing and with an identical machine.")],
 related=["electric-motor-overheating","reading-a-vibration-spectrum","pump-cavitation"]),
dict(fr="moteur-electrique-qui-chauffe", slug="electric-motor-overheating", machine="Electric motor", domaine="Industrial machinery", niveau="Intermediate",
 h1="Electric motor running hot: 5 causes to check",
 title="Electric motor overheating: causes and fixes",
 desc="Frame hotter than usual, smell of hot varnish: the causes of an overheating electric motor (fins, overload, voltage, phases) and what to do.",
 intro="The three-phase induction motor is robust, but it mostly dies of three things: its bearings, heat and humidity. A motor running hotter than usual ages fast, because heat degrades the winding insulation. The good news: the cause is often simple.",
 signes=["Frame clearly hotter than usual at the same load.","Smell of hot varnish or plastic.","Thermal overload relay tripping.","Louder humming."],
 causes=[("Dirty cooling fins or broken fan","Inspect the fan cover and fins, machine stopped"),("Mechanical overload (pump forcing, seized bearing)","Current on all three phases compared with the nameplate; turn the shaft by hand, locked out"),("Room too hot or poorly ventilated","Note the ambient temperature with every reading"),("Low or unbalanced voltage between phases","Measurement by a qualified electrician"),("Different currents between phases (loose terminal, worn contactor)","Clamp meter on each phase, by a qualified person")],
 faire=["Clean the fins and the fan guard, machine locked out.","Reduce the load or remove the cause on the driven machine.","Ventilate the plant room.","Have terminals tightened and cleaned, replace a worn contactor.","Smell of hot varnish: stop and find the cause before restarting."],
 secu="Current and voltage measurements inside a live panel are reserved for qualified, authorised personnel.",
 faq=[("What temperature is normal for a motor?","It depends on the motor. The most reliable approach is to compare with its own baseline, taken when it ran well, at comparable load and ambient temperature."),("Why does phase imbalance overheat a motor?","A small voltage imbalance creates a current imbalance several times larger, which heats the winding.")],
 related=["noisy-bearing","generator-will-not-start","reading-a-vibration-spectrum"]),
dict(fr="groupe-electrogene-ne-demarre-pas", slug="generator-will-not-start", machine="Generator set", domaine="Industrial machinery", niveau="Simple",
 h1="Standby generator that won’t start: check the battery first",
 title="Generator set won’t start: what to check",
 desc="Battery, diesel, cooling, light-load running, transfer switch: the weak points of a standby generator and the monthly test that prevents surprises.",
 intro="Where the grid is fragile, the generator protects the whole business. Its main weakness: it almost never works, and a machine that does not run hides its faults until the day it is needed. The most common cause of a failed start is the battery.",
 signes=["The starter turns slowly or not at all.","The engine starts then stalls.","Persistent black or white smoke.","The transfer switch does not change over during an outage."],
 causes=[("Flat battery or corroded terminals","Resting voltage: about 12.6 V for a charged 12 V battery; below 12.4 V, recharge"),("Water and microbes in the diesel, clogged filters","Drain the water separator and tank bottom"),("Cooling: low level, dirty radiator","Coolant level and condition, radiator, hoses"),("Fouling from running at very light load","Test history: no load or real load?"),("Faulty transfer switch","Real changeover test, not just engine start")],
 faire=["Check battery resting voltage monthly; keep terminals clean and tight and the charger on.","Drain the water separator and tank bottom; keep the tank full to limit condensation.","Run the monthly test under real load, aiming for at least a third of rated power for about thirty minutes, rather than off-load.","Really test the transfer switch.","Log every test: date, battery voltage, load, duration, observations."],
 secu="Diesel and exhaust gases: no heat source near a leak, test in a ventilated room, work with the engine stopped.",
 faq=[("Should a generator run off-load every week?","A monthly test under real load is better: a diesel running for long periods at very light load fouls up (unburnt fuel, soot)."),("Why is there water in the diesel?","Condensation settles at the bottom of the tank, especially in hot, humid climates, and feeds microbes that clog filters. A full tank and regular draining limit the problem.")],
 related=["electric-motor-overheating","compressor-runs-constantly","pump-cavitation"]),
dict(fr="compresseur-tourne-sans-arret", slug="compressor-runs-constantly", machine="Air compressor", domaine="Industrial machinery", niveau="Simple",
 h1="Air compressor running even when the shop is idle: find the leaks",
 title="Compressor runs constantly: compressed air leaks",
 desc="A compressor that runs when nobody uses air is paying for leaks. How to find them in the evening, and other causes: drains, cooler, filter.",
 intro="Compressed air is one of the most expensive forms of energy on a site. In poorly maintained installations, leaks commonly account for a large share of the air produced, sometimes 20 to 30%. Every leak makes the compressor run for nothing.",
 signes=["The compressor starts while nobody is using air.","Pressure no longer reaches the set point.","Hissing on the network in the evening.","Water in tools and pipework.","Shutdown on high temperature."],
 causes=[("Leaks on the network (fittings, hoses, drains)","Leak hunt in the evening, by ear and with soapy water"),("Blocked automatic drains, faulty dryer","Weekly check of drains"),("Dirty cooler, room too hot","Cooler cleanliness, room ventilation"),("Low oil level, clogged air filter","Oil level, filter condition")],
 faire=["In the evening, with the shop idle: listen to the network, apply soapy water to fittings, and note how fast pressure drops.","Repair the biggest leaks first.","Check automatic drains every week.","Clean the cooler, ventilate the room, replace the air filter.","If pressure stays low after all this: have the compressor diagnosed."],
 secu="Never point compressed air at a person; depressurise before undoing a fitting.",
 faq=[("How much does a compressed air leak cost?","A 3 mm hole on a 7 bar network releases roughly 10 litres of air per second. Producing that flow takes several kilowatts continuously: over a year, one leak of that size can cost thousands in electricity."),("How do I find an air leak?","In the evening, when the shop is quiet: by ear, then with soapy water, which bubbles at the leak.")],
 related=["electric-motor-overheating","generator-will-not-start","noisy-bearing"]),
dict(fr="climatisation-ne-refroidit-plus", slug="air-conditioner-not-cooling", machine="Air conditioning", domaine="Buildings and installations", niveau="Simple",
 h1="Air conditioner not cooling: checks before calling a technician",
 title="Air conditioner not cooling: what to check",
 desc="The AC blows but no longer cools? Filters, outdoor unit, settings, refrigerant: simple checks first, then when to call a certified technician.",
 intro="An air conditioner that blows without cooling very often has a simple cause: dirty filters or an outdoor unit that can no longer reject heat. A few checks without tools solve many cases. Low refrigerant, however, always needs a certified technician.",
 signes=["Air is barely cool.","The outdoor compressor runs non-stop.","The room no longer reaches the set point.","Ice on the pipes or the indoor unit.","Safety shutdown or error code."],
 causes=[("Dirty indoor unit filters","Open the cover, unit off, and look at the filters"),("Outdoor unit dirty, blocked or in full sun without airflow","Fins, leaves, objects in front, clearance around"),("Wrong mode or set point","Remote: cooling mode, set point, fan speed"),("Outdoor fan not running","Watch the fan while the compressor runs"),("Refrigerant shortage (leak)","Diagnosis by a certified technician only")],
 faire=["Check cooling mode and set point on the remote.","With the unit switched off: clean the filters as per the manual and let them dry completely.","Clear the outdoor unit: nothing in front or on top, clean fins, free airflow.","If ice forms: switch off and let it thaw before restarting.","If nothing changes, or the outdoor fan does not turn: call a certified technician. Recharging without fixing the leak solves nothing."],
 secu="Switch off the power before opening the unit. The refrigerant circuit may only be handled by a certified professional.",
 faq=[("How often should AC filters be cleaned?","According to the manual and use: in hot climates where the unit runs a lot, a check every few weeks is often needed."),("Should the gas be topped up every year?","No. A refrigeration circuit is sealed: if refrigerant is missing, there is a leak to find and repair.")],
 related=["generator-will-not-start","electric-motor-overheating","compressor-runs-constantly"]),
dict(fr="lire-un-spectre-vibratoire", slug="reading-a-vibration-spectrum", machine="Vibration analysis", domaine="Industrial machinery", niveau="Advanced",
 h1="Reading a vibration spectrum: unbalance, misalignment, bearings",
 title="Reading a vibration spectrum: typical faults",
 desc="Unbalance at 1×, misalignment at 1× and 2× axial, looseness, bearing defects: how to recognise common faults on an FFT spectrum.",
 intro="A pocket vibration meter gives an overall level. A vibration analyser goes further: it splits vibration into frequencies (FFT spectrum), and each fault leaves a signature. The patterns below are the most widely used in maintenance; they guide the diagnosis, which should always be confirmed by a second method or an inspection.",
 signes=["The overall vibration level rises on an important machine.","The pocket meter is no longer enough to find the cause.","Faults return after every repair.","You are planning a shutdown and want to know what to replace."],
 causes=[("Unbalance: dominant peak at 1× running speed, mainly radial","Compare horizontal, vertical and axial; check rotor fouling"),("Misalignment: strong 1× and 2×, with high axial vibration","Axial readings on both sides of the coupling, alignment check"),("Mechanical looseness: many harmonics of running speed","Tightness of feet and housings, soft foot"),("Bearing defect: peaks at non-synchronous frequencies linked to bearing geometry, often with sidebands","Defect frequencies calculated from the bearing reference; trend and envelope"),("Belts: peaks at belt-pass frequency, below running speed","Belt tension and pulley alignment")],
 faire=["Always measure at the same points (bearing housings) in all three directions, at normal load.","Record the exact running speed: the whole spectrum is read in multiples of it.","Compare with the machine’s baseline spectrum: the trend matters more than the value.","Confirm the fault with a second method (temperature, noise, inspection) before dismantling.","For critical equipment or complex faults, call a qualified vibration analyst."],
 secu="Measure only on fixed parts, away from moving parts, with guards in place.",
 faq=[("Is a pocket vibration meter enough?","To trend a small machine, yes: it measures overall vibration velocity in mm/s. To find the cause of vibration, a spectrum is far more precise."),("Why doesn’t 1× always mean unbalance?","Misalignment, a soft base or a bent shaft can also produce a 1× peak. Measurement direction and the other peaks help decide.")],
 related=["noisy-bearing","electric-motor-overheating","pump-cavitation"]),
]

METHODS_EN = [
dict(fr="types-de-maintenance", slug="types-of-maintenance", niveau="Simple",
 h1="Types of maintenance: corrective, preventive, condition-based, predictive",
 title="Types of maintenance explained",
 desc="Corrective, time-based preventive, condition-based and predictive maintenance: definitions, pros, limits and how to combine them on a small site.",
 intro="There is no single right maintenance strategy, but a mix suited to each machine. Choosing the right type for each asset avoids both surprise breakdowns and replacing parts that are still healthy.",
 sections=[("Corrective maintenance","<p>You act after the failure. Acceptable for an unimportant machine, a duplicated one or one that is quick to repair. For a critical machine it is the most expensive: unplanned downtime, emergency parts, overtime.</p>"),
  ("Time-based preventive maintenance","<p>You replace or inspect at fixed intervals, whether the part is worn or not: oil changes, filters, belts. Easy to organise, but failures still slip through between interventions and good parts get thrown away.</p>"),
  ("Condition-based maintenance","<p>You monitor the real condition of the machine (temperature, vibration, noise, current, oil) and act only when the signs justify it. This is the MaintenanceIQ method: it uses the <a href=\"/en/methods/p-f-curve/\">P-F interval</a>, the time between a detectable defect and the failure.</p>"),
  ("Predictive maintenance","<p>It goes further: from the trend of measurements it estimates when a defect will become critical, often with connected sensors and software. Useful for large plants; for a small site, well-run condition-based maintenance already delivers most of the benefit.</p>"),
  ("How to combine them","<ul><li>Critical machines (A): weekly condition monitoring + manufacturer’s preventive tasks.</li><li>Important machines (B): less frequent monitoring + preventive tasks.</li><li>Secondary machines (C): simple preventive, or even corrective.</li></ul><p>To rank your machines, see <a href=\"/en/methods/machine-criticality/\">criticality in 10 minutes</a>.</p>")],
 faq=[("What is the difference between preventive and condition-based maintenance?","Time-based preventive acts at fixed intervals; condition-based acts when the measured condition of the machine justifies it."),("Do I need sensors for condition-based maintenance?","No. Your senses, an infrared thermometer, a stethoscope and a pocket vibration meter are enough to start, as long as you measure regularly and consistently.")],
 fiches=["noisy-bearing","generator-will-not-start"]),
dict(fr="courbe-p-f", slug="p-f-curve", niveau="Simple",
 h1="The P-F curve: your window to act before failure",
 title="The P-F curve and P-F interval explained",
 desc="Point P (detectable defect), point F (failure) and the P-F interval: how this curve sets the frequency of your inspections.",
 intro="Almost all mechanical and electrical failures follow the same path: a defect appears, grows slowly, then faster and faster, until failure. The P-F curve describes this path and gives the rule for inspection frequency.",
 sections=[("P and F","<p><strong>P</strong> (potential failure) is when the defect becomes detectable. <strong>F</strong> (functional failure) is the breakdown. The P-F interval ranges from a few days to several months depending on the defect.</p>"),
  ("Detect early, gain time","<p>Typical order of appearance: vibration and ultrasound, particles in the oil, audible noise, heat to the touch, then smoke and breakage. A vibration meter detects a damaged bearing long before the ear, and the ear long before the hand.</p>"),
  ("The frequency rule","<p>Inspect at least twice during the P-F interval, i.e. at an interval no longer than half of P-F. If a bearing defect takes about six weeks to go from “detectable” to “broken”, a reading every two to three weeks will catch it.</p>")],
 faq=[("Does the P-F curve predict the failure date?","No. It helps you enter the action window early enough to repair when you decide."),("How do I know a machine’s P-F interval?","From experience, manufacturer feedback and failure history. Without data, start cautiously with frequent checks on critical machines.")],
 fiches=["noisy-bearing","reading-a-vibration-spectrum"]),
dict(fr="criticite-des-machines", slug="machine-criticality", niveau="Simple",
 h1="Rank your machines by criticality in 10 minutes",
 title="Machine criticality: the A, B, C grid",
 desc="A simple four-criteria grid to rank your machines A, B or C and decide how often to inspect them. Worked example included.",
 intro="You cannot monitor everything with the same attention, and you do not need to. Score each machine from 1 to 3 on four criteria, add them up, and you know where to focus.",
 sections=[("The four criteria","<div class=\"tw\"><table><thead><tr><th>Criterion</th><th>1 point</th><th>2 points</th><th>3 points</th></tr></thead><tbody><tr><td>Production impact</td><td>None or low</td><td>Slows activity</td><td>Stops activity</td></tr><tr><td>Safety and environment</td><td>No risk</td><td>Limited risk</td><td>Risk to people, leak, fire</td></tr><tr><td>Parts and repair time</td><td>In stock, a few hours</td><td>A few days</td><td>Imported, several weeks</td></tr><tr><td>Backup</td><td>Duplicate machine</td><td>Partial or manual backup</td><td>No backup</td></tr></tbody></table></div>"),
  ("Reading the score","<ul><li><strong>10–12, class A (critical)</strong>: weekly readings, full machine record, critical spares in stock.</li><li><strong>7–9, class B</strong>: readings every two weeks, weekly visual and listening check.</li><li><strong>4–6, class C</strong>: monthly check, greasing as per manufacturer.</li></ul>"),
  ("Example","<p>The water transfer pump of a bottling plant, with no backup, whose motor takes three weeks to import: 3 + 2 + 3 + 3 = 11, class A. A changing-room fan: 1 + 1 + 1 + 2 = 5, class C.</p>")],
 faq=[("Should the grid be redone regularly?","Yes, whenever things change: a new backup machine, a part now stocked, reorganised production."),("What comes first for a class A machine?","Record its baseline readings while it runs well, and make sure its critical spares are available.")],
 fiches=["pump-cavitation","generator-will-not-start"]),
dict(fr="mtbf-mttr-disponibilite", slug="mtbf-mttr-availability", niveau="Intermediate",
 h1="MTBF, MTTR and availability: calculate and improve",
 title="MTBF, MTTR and availability: formulas",
 desc="Definitions and formulas for MTBF, MTTR and availability, with a worked example and practical levers to improve each one.",
 intro="Three indicators are enough to steer a machine’s reliability: mean time between failures (MTBF), mean time to repair (MTTR) and the resulting availability.",
 sections=[("The formulas","<ul><li><strong>MTBF</strong> = operating time ÷ number of failures.</li><li><strong>MTTR</strong> = total repair downtime ÷ number of repairs.</li><li><strong>Availability</strong> = MTBF ÷ (MTBF + MTTR).</li></ul>"),
  ("Example","<p>Illustrative example: a pump ran 2,000 hours over six months with 4 failures totalling 40 hours of repair. MTBF = 2,000 ÷ 4 = 500 h. MTTR = 40 ÷ 4 = 10 h. Availability = 500 ÷ (500 + 10) ≈ 98%.</p>"),
  ("Improve MTBF","<p>Fix root causes (lubrication, alignment, looseness, contamination, heat, electrical issues) and monitor condition to act before failure.</p>"),
  ("Reduce MTTR","<p>Critical spares in stock (especially far from suppliers), procedures and tools ready, fast diagnosis, machine history at hand.</p>")],
 faq=[("Is MTBF a guaranteed lifetime?","No. It is an average calculated from history: use it to follow a trend and compare, not to predict a specific failure."),("What availability should I aim for?","It depends on the cost of downtime. Above all, compare your availability with itself over time.")],
 fiches=["noisy-bearing"]),
dict(fr="analyse-des-causes-racines", slug="root-cause-analysis", niveau="Intermediate",
 h1="Root cause analysis: 5 Whys and the Ishikawa diagram",
 title="Root cause analysis: the 5 Whys method",
 desc="Why the same failure keeps coming back: find the root cause with the 5 Whys and the Ishikawa (fishbone) diagram. Method and real example.",
 intro="Replacing a part without asking why it failed schedules the next breakdown. Root cause analysis works back from the visible effect to the cause which, once fixed, stops the failure from recurring.",
 sections=[("The 5 Whys","<p>Ask “why?” repeatedly until you reach a cause you can act on.</p><ol><li>Why did the pump stop? The bearing broke.</li><li>Why? It overheated.</li><li>Why? It lacked grease.</li><li>Why? Greasing was not scheduled.</li><li>Why? No greasing list existed for this machine.</li></ol><p>Action: a greasing plan with point, grease, quantity and frequency. Replacing the bearing alone would have solved nothing.</p>"),
  ("The Ishikawa (fishbone) diagram","<p>For problems with several causes, sort possible causes into families: Materials, Machine, Method, Manpower, Milieu (environment). In hot, humid or salty climates, the environment weighs heavily.</p>"),
  ("Good practice","<ul><li>Start from facts (removed part, photos, readings), not assumptions.</li><li>Keep the failed part: its appearance often tells the cause.</li><li>Check after the action that the failure does not return.</li></ul>")],
 faq=[("Do I always have to ask exactly five whys?","No. Five is a guide: stop when you reach a cause that allows a concrete action."),("When should I do a root cause analysis?","For any repeated failure, and any costly or dangerous one.")],
 fiches=["noisy-bearing","reading-a-vibration-spectrum"]),
]
